// import React, { useState } from 'react';
// import logo from '../../../assets/logo.png';

function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] p-4">
      <div className="flex items-center justify-between flex-wrap md:flex-nowrap">
        {/* Logo */}
        <img src={logo} alt="Logo" className="h-12" />

        {/* Mobile Menu Toggle */}
        <div className="ml-auto md:hidden">
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className={`text-2xl font-bold transition-transform duration-300 ease-in-out ${
              isMenuOpen ? 'rotate-180' : 'rotate-0'
            }`}
            aria-label="Toggle menu"
          >
            ☰
          </button>
        </div>

        {/* Nav + Button Container */}
        <div
          className={`w-full md:w-auto flex-col md:flex-row md:flex md:justify-center md:items-center md:gap-6
            transition-all duration-300 ease-in-out
            ${
              isMenuOpen
                ? 'opacity-100 translate-y-0 pointer-events-auto'
                : 'opacity-0 -translate-y-5 pointer-events-none md:pointer-events-auto md:opacity-100 md:translate-y-0'
            }
          `}
        >
          {/* Nav Links */}
          <nav className="flex flex-col items-center gap-3 md:flex-row md:gap-6 text-[clamp(0.9rem,2vw,1.1rem)] font-semibold">
            <a href="#" className="text-[#f48f0f]">Home</a>
            <a href="#" className="text-[#292929]">About</a>
            <a href="#" className="text-[#292929]">Gallery</a>
            <a href="#" className="text-[#292929]">Education</a>
          </nav>

          {/* Button */}
          <div className="mt-4 md:mt-0 md:ml-6">
            <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
              Become a member
            </button>
          </div>
        </div>
      </div>
    </header>
  );
}

export default Navbar;
